command:
/**
 * 猎杀对决 · 路上随机表
 * - 若世界没有 RollTable，则创建
 * - 然后掷一次并贴到聊天
 */
const TABLE_NAME = "猎杀对决 · 路上随机表";
const RESULTS = [
  { range: [1, 1], text: "【死寂路段】暂无遭遇。可休整/整理弹药，或远处一声枪响（氛围）。" },
  { range: [2, 2], text: "【血迹未干】新鲜拖痕。Survival/Perception DC18：找线索；大失败引 1d4 僵尸。" },
  { range: [3, 3], text: "【杂兵游荡】2d4 徒手/砍刀僵尸从灌木钻出，以拖延为主。" },
  { range: [4, 4], text: "【火把僵尸】1d3 火把杂兵；死后火把可能点燃油/拌雷。" },
  { range: [5, 5], text: "【遗弃辎重】马车/气球残骸。有弹药或针剂；Perception DC20 否则踩警报拌雷。" },
  { range: [6, 6], text: "【别人的绊线】路中央隐藏铁丝网/毒气拌雷（隐匿 DC19）。察觉→绕开/拆/引爆。" },
  { range: [7, 7], text: "【26军团哨兵】1～2 名疲惫侦察兵（或一具尸体）。可换情报、护送或被误认敌对。" },
  { range: [8, 8], text: "【炊烟疑云】炖肉香料味——神秘厨师方向？营地或诱饵。" },
  { range: [9, 9], text: "【腐化动物】不对劲的鸟/沼鳄挡路。威吓或绕路；开战为短遭遇。" },
  { range: [10, 10], text: "【浓雾迷路】Survival DC20，失败多耗 1 小时且下次随机 +2（上限 20）。" },
  { range: [11, 11], text: "【敌对猎人】要过路费或抢情报。谈判/恐吓/短冲突后散开。" },
  { range: [12, 12], text: "【蜂鸣与蛭影】预告附近蜂巢/肉头。可主动猎或加速撤。" },
  { range: [13, 13], text: "【焦土余烬】喷火怪/狱生足迹。Nature DC18 判断时间；可能有灼烬格。" },
  { range: [14, 14], text: "【树上悬赏】过期/错误合同，或指向隐藏赏金的半真线索。" },
  { range: [15, 15], text: "【断桥洪水】搭路或绕远；绕远则再骰一次路上表。" },
  { range: [16, 16], text: "【腐化低语】Will DC18；失败惊惧1或短时幻觉。" },
  { range: [17, 17], text: "【真补给/假好意】路边药箱。Crafting/Medicine DC18：真回复 / 假毒气或毒绷带。" },
  { range: [18, 18], text: "【血月先兆】天色异红。下场战斗可轻血月（怪+1）或提示开血月开关。" },
  { range: [19, 19], text: "【放逐残响】发现令牌碎片/残渣，或听见 Boss 方向低吼（推主线）。" },
  { range: [20, 20], text: "【屠夫的记号】血手印/挂钩/半扇兽尸。强线索向屠夫巢——或恐吓伪装。" },
];

if (!game.user.isGM) {
  return ui.notifications.warn("需要 GM 才能掷路上随机表。");
}

let table = game.tables.find((t) => t.name === TABLE_NAME);
if (!table) {
  const results = RESULTS.map((r, i) => ({
    type: CONST.TABLE_RESULT_TYPES?.TEXT ?? "text",
    range: r.range,
    text: r.text,
    weight: 1,
    drawn: false,
  }));
  table = await RollTable.create({
    name: TABLE_NAME,
    description: "猎杀对决路易斯安那路上遭遇。行军/换区时掷。",
    formula: "1d20",
    replacement: true,
    displayRoll: true,
    results,
  });
  ui.notifications.info(`已创建掷骰表：「${TABLE_NAME}」`);
}

const draw = await table.draw({ displayChat: true });
